          "anchors": [
            {
              "line_start": 443,
              "line_end": 443,
              "support": "Fitted power law E_i = (19.774 ± 5.010) × 10^4 tau_Q^{-0.971 ± 0.052} for panel (a) at T=10^-6."
            }
          ]
        },
        {
          "name": "Ei_amplitude_T_one",
          "value": 95430.0,
          "uncertainty": "\\pm 2.951 \\times 10^4 (source_unspecified)",
